package org.example;

import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.nio.file.StandardOpenOption;
import java.util.List;

public class Lightcel {
    private final CsvReader csvr;
    private final Table table;
    private final Tokenizer tokenizer;
    private final Parser parser;
    private final Evaluator evaluator;

    public final String VERSION = "0.0.1";

    public Lightcel(CsvReader csvr, Table table, Tokenizer tokenizer, Parser parser, Evaluator evaluator) {
        this.csvr = csvr;
        this.table = table;
        this.tokenizer = tokenizer;
        this.parser = parser;
        this.evaluator = evaluator;
    }

    public void start(String[] args) {
        // System.out.println(System.getProperty("user.dir"));

        if (args.length == 0 || args.length > 2) {
            IO.println("usage: lightcel [-v | --version] [-h | --help] <command> [<args>]\n");
            return;
        }

        if (args[0].equals("-v") || args[0].equals("--version")) {
            IO.println("lightcel version " + VERSION);
            return;
        }

        if (args[0].equals("-h") || args[0].equals("--help")) {
            IO.println("usage: lightcel [-v | --version] [-h | --help]  <command> [<args>]\n");
            IO.println("How to use Lightcel:\n");
            IO.println("commands");
            IO.println("   parse   takes input.csv and produces output.csv with excel functionality");
            return;
        }

        if (args[0].equals("parse") && (args[1].equals("-h") || args[1].equals("--help"))) {
            IO.println("usage: lightcel parse [<arg.csv>]\n");
            return;
        }

        if (args[0].equals("parse") && args[1].endsWith(".csv")) {
            String inputFile = args[1];
            csvr.importCsv(inputFile);
            printTable();
            createOutputFile();
        } else {
            IO.println("lightcel: '" + args[0] + "' is not a lightcel command. See 'lightcel --help'.");
        }
    }

    void createOutputFile() {
        Path path = Paths.get("output.csv");
        try (BufferedWriter bw = Files.newBufferedWriter(path, StandardOpenOption.CREATE)) {
            String line = "";

            for (int row = 0; row <= table.getMaxInsertedRow(); row++) {
                for (int col = 0; col <= table.getMaxInsertedCol(); col++) {
                    Cell cell = table.getCell(row, col);
                    if (cell != null) {
                        CellType type = cell.getCellType();

                        String value = "";
                        if (cell.getValue() != null) {
                            value = cell.getValue().toString();
                        }

                        switch (type) {
                            case EMPTY -> line += ",";
                            case BOOLEAN -> {
                                line += value.toUpperCase() + ",";
                            }
                            case STRING, NUMBER -> line += value + ",";
                            case FORMULA -> {
                                line += value + ",";
                                List<Token> tokens = tokenizer.tokenize(value);
                                tokenizer.printTokenList(tokens);
                                parser.parse(tokens);
                            }
                        }
                    }
                }
                bw.write(line);
                bw.newLine();
                line = "";
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

   
    void printTable() {
        IO.println("Printing Table Structure...\n");

        for (int row = 0; row <= table.getMaxInsertedRow(); row++) {
            for (int col = 0; col <= table.getMaxInsertedCol(); col++) {
                if (table.getCell(row, col) == null) {
                    IO.print("  ");
                } else {
                    IO.print(table.getCell(row, col).getValue() + "(" + table.getCell(row, col).getCellType() + ") ");
                }
            }
            if (row <= 2) {
                IO.println();
            }
        }

        IO.println("-------------------------------");
    }
}
